    {
        this.service = service;
        LOGGER.setUseParentHandlers(false);	// only want to output to the provided LogHandler
    }

// test methods
    @Test
    /**
     * Full Create-Read-Update-Delete of a APU, through a APUTest.
     */
    public void testCRUD() throws Throwable {
    try {
        LOGGER.info( "**********************************************************" );
        LOGGER.info( "Beginning full test on APUTest..." );

        testCreate();
        testRead();
        testUpdate();
        testGetAll();
        testDelete();

        LOGGER.info( "Successfully ran a full test on APUTest..." );
        LOGGER.info( "**********************************************************" );
        LOGGER.info( "" );
    }
    catch( Throwable e ) {
        throw e;
    }
    finally  {
        if ( handler != null ) {
            handler.flush();
            LOGGER.removeHandler(handler);
        }
    }
}

    /**
     * Tests creating a new APU.
     *
     * @return    APU
     */
    public APU testCreate() throws Throwable {
    APU entity = null;

    LOGGER.info( "APUTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a APU");

    StringBuilder msg = new StringBuilder( "-- Failed to create a APU" );

    try {
        entity = service.createAPU( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getAPUId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a APU with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

    /**
     * Tests reading a APU.
     *
     * @return    APU
     */
    public APU testRead() throws Throwable {
    LOGGER.info( "APUTest:testRead()" );
    LOGGER.info( "-- Reading a previously created APU" );

    APU entity = null;
    StringBuilder msg = new StringBuilder( "-- Failed to read APU with primary key" );
    msg.append( theId );

    try {
        entity = service.getAPU( new APUFetchOneSummary(theId) );

        assertNotNull( entity,msg.toString() );

        // for use later
        theId = entity.getAPUId();

        LOGGER.info( "-- Successfully found APU " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests updating a APU.
     *
     * @return    APU
     */
    public APU testUpdate() throws Throwable {
    LOGGER.info( "APUTest:testUpdate()" );
    LOGGER.info( "-- Attempting to update a APU." );

    StringBuilder msg = new StringBuilder( "Failed to update a APU : " );
    APU entity = null;

    try {
        UpdateAPUCommand updateCommand = this.generateUpdateCommand();

        // apply the current id as to update the fields of the current entity
        updateCommand.setAPUId( theId );

        assertNotNull( updateCommand, msg.toString() );

        LOGGER.info( "-- Now updating the created APU." );

        entity = service.updateAPU( updateCommand );

        assertNotNull( entity, msg.toString()  );

        LOGGER.info( "-- Successfully saved APU - " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : primarykey-" + theId + " : entity-" +  entity + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests deleting a APU.
     */
    public void testDelete() throws Throwable {
    LOGGER.info( "APUTest:testDelete()" );
    LOGGER.info( "-- Deleting a previously created APU." );

    try {
        DeleteAPUCommand deleteCommand = new DeleteAPUCommand( theId );

        service.delete( deleteCommand );

        LOGGER.info( "-- Successfully deleted APU with primary key " + theId );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( "-- Failed to delete APU with primary key " + theId );

        throw e;
    }
}

    /**
     * Tests getting all APUs.
     *
     * @return    Collection
     */
    public List<APU> testGetAll() throws Throwable {
    LOGGER.info( "APUTest:testGetAll() - Retrieving Collection of APUs:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all APU : " );
    List<APU> collection  = null;

    try {
        // call the static get method on the APUService
        collection = service.getAllAPU();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            APU currEntity  = null;
            Iterator<APU> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getAPUId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

    public APUTest setHandler( Handler handler ) {
    this.handler = handler;
    LOGGER.addHandler(handler);	// assign so the LOGGER can only output results to the Handler
    return this;
}


