	protected UpdateAPUCommand generateUpdateCommand() {
    UpdateAPUCommand command = new UpdateAPUCommand( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  null,  new HashSet<>() );

    return( command );
}
